/* Generated by tools/gen_setting_slots.py: the RAM slot SETTING_GET (0x403FFCD0) reads for each
 * key, proven by replay equivalence of the complete original getter (stock C2.01).
 * Read with one aligned 32-bit load (z63g_ld32); never write a slot. Do not edit. */
#ifndef Z63_SETTING_SLOTS_H
#define Z63_SETTING_SLOTS_H
#define Z63_SLOT_FILE_TYPE  0xa03f0eee0ull   /* key 0x06000f06: recording file type */
#define Z63_SLOT_KEY_0F55   0xa03f0f12cull   /* key 0x05000f55: item 0x0F55 (group 5) */
#define Z63_SLOT_KEY_201B   0xa03f2100cull   /* key 0x0400201b: item 0x201B (group 4) */
#define Z63_SLOT_KEY_0F3F   0xa03f0efc4ull   /* key 0x07000f3f: item 0x0F3F (group 7; size getter input, meaning not established) */
#define Z63_SLOT_KEY_0F40   0xa03f0efc8ull   /* key 0x07000f40: item 0x0F40 (group 7; rate getter input, meaning not established) */
#define Z63_SLOT_KEY_0502   0xa03f09cf8ull   /* key 0x06000502: ordinary image-quality type (0 RAW+JPEG, 1 RAW, 3 JPEG) */
#endif
